public class Period_normalizedStandard_TriageGen2Test {



    @Test
    public void testNormalizedStandard_WithYearsAndMonthsSupported() {
        // Test normalization where years and months are supported by the type
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        PeriodType type = PeriodType.standard(); // supports years and months
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getYears());
